const net = require('net');
const { spawn } = require('child_process');
const server = spawn('node', ['server.js'], { env: { ...process.env, PORT: '8099' }, stdio: 'inherit' });
const send = (text) => new Promise((resolve) => {
  const sock = net.connect(8099, '127.0.0.1', () => sock.write(text, 'latin1'));
  let out = '';
  sock.on('data', (d) => (out += d.toString('latin1')));
  sock.on('close', () => resolve(out.split('\\r\\n')[0] + ' | ' + out.split('\\r\\n').pop()));
  sock.on('error', () => {});
  setTimeout(() => { if ("'!out) { sock.end(); } }, 500);
});
